package com.vynedam.stockai.controller; import com.vynedam.stockai.dto.OperationsDtos.SupplierRequest; import com.vynedam.stockai.model.Supplier; import com.vynedam.stockai.service.SupplierService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/suppliers")public class SupplierController{private final SupplierService s;public SupplierController(SupplierService x){s=x;}@GetMapping List<Supplier>list(){return s.list();}@PostMapping@PreAuthorize("hasAnyRole('SUPER_ADMIN','PURCHASE_MANAGER')")ResponseEntity<Supplier>create(@Valid@RequestBody SupplierRequest r){return ResponseEntity.status(201).body(s.create(r));}@PutMapping("/{id}")@PreAuthorize("hasAnyRole('SUPER_ADMIN','PURCHASE_MANAGER')")Supplier update(@PathVariable String id,@Valid@RequestBody SupplierRequest r){return s.update(id,r);}}
